class Gradebook:
    def __init__(self) -> None:
        self.assignments: dict[str, dict] = {}
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the allowed scale 2.0 to 5.0.")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = float(grade)

    def students(self) -> list[str]:
        return sorted([student for student, grades in self.grades.items() if grades])

    def average(self, student: str) -> float:
        if not self.assignments:
            return 0.0

        student_grades = self.grades.get(student, {})

        # Collect all assignments with student's grades (defaulting to 2.0)
        quizzes = []
        homeworks = []

        for name, info in self.assignments.items():
            grade = student_grades.get(name, 2.0)
            weight = info["weight"]
            kind = info["kind"]
            if kind == "quiz":
                quizzes.append((name, grade, weight))
            else:
                homeworks.append((name, grade, weight))

        # If student has more than one quiz, drop the lowest quiz grade.
        # Ties can drop any one quiz with the lowest grade.
        if len(quizzes) > 1:
            lowest_idx = min(range(len(quizzes)), key=lambda i: quizzes[i][1])
            quizzes.pop(lowest_idx)

        total_weighted_sum = 0.0
        total_weight = 0.0

        for _, grade, weight in homeworks + quizzes:
            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
```

